#!/usr/bin/env python3
from __future__ import annotations
import argparse, base64, datetime as dt, importlib.util, os, py_compile, shutil, subprocess, sys
from pathlib import Path

VERSION='0.8.0'
MODIFIED_B64={'backend/app/api/v1/endpoints/vision_app_api.py': {'old': '', 'new': ''}, 'backend/app/services/vision_app/models.py': {'old': '', 'new': ''}, 'backend/app/services/vision_app/repository.py': {'old': '', 'new': ''}, 'backend/app/services/vision_app/roi_search.py': {'old': '', 'new': ''}, 'backend/app/services/vision_app/runtime.py': {'old': '', 'new': ''}, 'frontend/src/Pages/ComputerVisionPage.tsx': {'old': '', 'new': ''}, 'frontend/src/api/visionAppApi.ts': {'old': '', 'new': ''}, 'frontend/src/components/ComputerVision/ComputerVision.css': {'old': '', 'new': ''}, 'frontend/src/components/ComputerVision/MasterSamplePanel.tsx': {'old': '', 'new': ''}, 'frontend/src/components/ComputerVision/VisionViewport.tsx': {'old': '', 'new': ''}, 'frontend/src/components/ComputerVision/WorkingModulePanel.tsx': {'old': '', 'new': ''}, 'frontend/tools/generate_llm_context_map.py': {'old': '', 'new': ''}}
CREATED_B64={'backend/app/services/vision_app/camera_runtime.py': '', 'backend/app/services/vision_app/debug_store.py': '', 'backend/app/services/vision_app/decision_runtime.py': '', 'backend/app/services/vision_app/runner.py': '', 'backend/tests/vision_app/test_vision_app_v0800.py': '', 'frontend/docs/llm_context/updates/v0800_computer_vision_production_pipeline.md': '', 'frontend/src/components/ComputerVision/CameraModulePanel.tsx': '', 'frontend/src/components/ComputerVision/ScopeEditorModal.tsx': ''}
MODIFIED={k:{'old':base64.b64decode(v['old']).decode(),'new':base64.b64decode(v['new']).decode()} for k,v in MODIFIED_B64.items()}
CREATED={k:base64.b64decode(v).decode() for k,v in CREATED_B64.items()}

def resolve_roots(fe_arg=None,be_arg=None):
    cwd=Path.cwd().resolve(); fes=[];bes=[]
    if fe_arg:fes.append(Path(fe_arg).expanduser().resolve())
    if be_arg:bes.append(Path(be_arg).expanduser().resolve())
    fes += [cwd,cwd/'LambdaVisionSuper',cwd.parent/'LambdaVisionSuper']
    bes += [cwd,cwd/'LambdaVisionSuperBackEnd',cwd.parent/'LambdaVisionSuperBackEnd']
    fe=next((p for p in fes if (p/'src/App.tsx').exists() and (p/'src/Pages/ComputerVisionPage.tsx').exists()),None)
    be=next((p for p in bes if (p/'app/main.py').exists() and (p/'app/services/vision_app/models.py').exists()),None)
    if not fe: raise RuntimeError('Cannot locate LambdaVisionSuper frontend; use --frontend')
    if not be: raise RuntimeError('Cannot locate LambdaVisionSuperBackEnd; use --backend')
    return fe,be

def real(fe,be,v):
    if v.startswith('frontend/'): return fe/v[len('frontend/'):]
    if v.startswith('backend/'): return be/v[len('backend/'):]
    raise ValueError(v)

def mstate(p,old,new):
    if not p.exists():return 'MISSING'
    t=p.read_text(encoding='utf-8')
    if t==new:return 'OK'
    if t==old:return 'UPDATE'
    return 'CONFLICT'

def cstate(p,new):
    if not p.exists():return 'CREATE'
    return 'OK' if p.read_text(encoding='utf-8')==new else 'CONFLICT'

def scan(fe,be):
    print('='*104);print('COMPUTER VISION V0.8.0 — CAMERA + PRODUCTION WORKING PIPELINE');print('='*104)
    print('Frontend :',fe);print('Backend  :',be);print(); conflicts=0
    for v,pay in MODIFIED.items():
        s=mstate(real(fe,be,v),pay['old'],pay['new']);print(f'  [{s:12}] {v}');conflicts += s in {'CONFLICT','MISSING'}
    for v,new in CREATED.items():
        s=cstate(real(fe,be,v),new);print(f'  [{s:12}] {v}');conflicts += s=='CONFLICT'
    req=be/'requirements.txt'; rs='OK' if req.exists() and 'pypylon' in req.read_text(encoding='utf-8').lower() else ('PATCH' if req.exists() else 'SKIP')
    print(f'  [{rs:12}] backend/requirements.txt (optional Basler pypylon dependency)')
    print('\nv0.8 contract:')
    print('  Program lifecycle: Save + Remove')
    print('  Camera: Manual upload | Basler/pypylon | generic HTTP capture/focus URL')
    print('  Automatic runner: Modbus rising edge -> camera capture -> inspect -> OK/NG pulse')
    print('  Master: one ROI locator family for all stations + blur preview')
    print('  Working: Global Filter -> Logic -> Decision -> ROI locate -> station Filter/Logic/Decision')
    print('  Stations: sequential or parallel')
    print('  Debug: real filter-stage images + zoom/pan viewport + collapsible panels + large OK/NG box')
    print('  Benchmark: per filter/locator/logic/decision/total timing')
    print('  Decision: restricted if/else mathematical DSL over Logic outputs')
    print('  Context generator + v0.8 handoff MD included')
    if conflicts: print(f'\n[WARN] {conflicts} conflict(s); apply will stop safely.')
    return 0

def preflight(fe,be):
    errs=[]
    for v,pay in MODIFIED.items():
        s=mstate(real(fe,be,v),pay['old'],pay['new'])
        if s not in {'UPDATE','OK'}: errs.append(f'{v}: {s}')
    for v,new in CREATED.items():
        s=cstate(real(fe,be,v),new)
        if s not in {'CREATE','OK'}: errs.append(f'{v}: {s}')
    app=(fe/'src/App.tsx').read_text(encoding='utf-8')
    api=(be/'app/api/v1/api.py').read_text(encoding='utf-8')
    if '/computer-vision' not in app: errs.append('frontend/src/App.tsx: v0.7 Computer Vision route missing')
    if 'vision_app_api' not in api or 'computer-vision' not in api: errs.append('backend/app/api/v1/api.py: v0.7 Computer Vision router missing')
    if errs: raise RuntimeError('Safe update stopped:\n  - '+'\n  - '.join(errs))

def backup(fe,be,paths):
    root=fe/'.lambda_updater_backups'/f'computer_vision_v0800_{dt.datetime.now().strftime("%Y%m%d_%H%M%S")}'
    root.mkdir(parents=True,exist_ok=True)
    for p in paths:
        if not p.exists():continue
        try: rel=p.relative_to(fe); dst=root/'frontend'/rel
        except ValueError: rel=p.relative_to(be); dst=root/'backend'/rel
        dst.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,dst)
    return root

def patch_requirements(be):
    p=be/'requirements.txt'
    if not p.exists(): return False
    t=p.read_text(encoding='utf-8')
    if 'pypylon' in t.lower():return False
    p.write_text(t.rstrip()+'\n# Basler camera support (lazy-imported by Computer Vision)\npypylon>=4.0\n',encoding='utf-8');return True

def regenerate_context(fe,be):
    g=fe/'tools/generate_llm_context_map.py'
    if not g.exists(): print('[SKIP] context generator missing');return
    cmd=[sys.executable,str(g),'--frontend',str(fe),'--backend',str(be)]
    if '--output-dir' in g.read_text(encoding='utf-8'):cmd += ['--output-dir',str(fe/'docs/llm_context')]
    p=subprocess.run(cmd,cwd=str(fe),text=True,capture_output=True)
    if p.returncode: raise RuntimeError('Context generator failed:\n'+(p.stdout+'\n'+p.stderr).strip())
    if p.stdout.strip():print(p.stdout.strip())

def apply(fe,be):
    preflight(fe,be)
    paths=[real(fe,be,v) for v in list(MODIFIED)+list(CREATED)]+[be/'requirements.txt']
    b=backup(fe,be,paths)
    for v,pay in MODIFIED.items():
        p=real(fe,be,v)
        if p.read_text(encoding='utf-8')!=pay['new']:p.write_text(pay['new'],encoding='utf-8');print('[WRITE]',v)
    for v,new in CREATED.items():
        p=real(fe,be,v);p.parent.mkdir(parents=True,exist_ok=True)
        if not p.exists() or p.read_text(encoding='utf-8')!=new:p.write_text(new,encoding='utf-8');print('[WRITE]',v)
    if patch_requirements(be):print('[PATCH] backend/requirements.txt + pypylon')
    print('[INFO] Regenerating LLM context docs...');regenerate_context(fe,be)
    print('[OK] Backup:',b);print('Run verify next.');return 0

def python_syntax(be):
    fs=[];errs=[]
    for v in list(MODIFIED)+list(CREATED):
        if v.startswith('backend/') and v.endswith('.py'):
            p=real(Path('/unused'),be,v);fs.append(p)
            try:py_compile.compile(str(p),doraise=True)
            except Exception as e:errs.append(f'{p.relative_to(be)}: {e}')
    return len(fs),errs

def ts_transpile(fe):
    fs=[real(fe,Path('/unused'),v) for v in list(MODIFIED)+list(CREATED) if v.startswith('frontend/') and v.endswith(('.ts','.tsx'))]
    code='''const fs=require("fs"),ts=require("typescript");let bad=false;for(const f of process.argv.slice(1)){const r=ts.transpileModule(fs.readFileSync(f,"utf8"),{fileName:f,reportDiagnostics:true,compilerOptions:{jsx:ts.JsxEmit.ReactJSX,target:ts.ScriptTarget.ES2020,module:ts.ModuleKind.ESNext}});const e=(r.diagnostics||[]).filter(x=>x.category===ts.DiagnosticCategory.Error);if(e.length){bad=true;console.error("TS_ERROR",f);e.forEach(x=>console.error(ts.flattenDiagnosticMessageText(x.messageText,"\\n")));}}process.exit(bad?1:0);'''
    env=dict(os.environ);nr=subprocess.run(['npm','root','-g'],text=True,capture_output=True)
    if nr.returncode==0 and nr.stdout.strip():env['NODE_PATH']=nr.stdout.strip()+(os.pathsep+env['NODE_PATH'] if env.get('NODE_PATH') else '')
    return subprocess.run(['node','-e',code,*map(str,fs)],cwd=str(fe),env=env,text=True,capture_output=True)

def verify(fe,be,skip_build=False):
    print('='*104);print('VERIFY COMPUTER VISION V0.8.0');print('='*104);fail=0
    page=(fe/'src/Pages/ComputerVisionPage.tsx').read_text(encoding='utf-8');api=(be/'app/api/v1/endpoints/vision_app_api.py').read_text(encoding='utf-8');runtime=(be/'app/services/vision_app/runtime.py').read_text(encoding='utf-8');models=(be/'app/services/vision_app/models.py').read_text(encoding='utf-8');master=(fe/'src/components/ComputerVision/MasterSamplePanel.tsx').read_text(encoding='utf-8');work=(fe/'src/components/ComputerVision/WorkingModulePanel.tsx').read_text(encoding='utf-8');viewport=(fe/'src/components/ComputerVision/VisionViewport.tsx').read_text(encoding='utf-8');cam=(be/'app/services/vision_app/camera_runtime.py').read_text(encoding='utf-8');runner=(be/'app/services/vision_app/runner.py').read_text(encoding='utf-8');decision=(be/'app/services/vision_app/decision_runtime.py').read_text(encoding='utf-8')
    checks=[
      ('Program remove UI/API','removeProgram' in page and '@router.delete("/programs/{program_id}"' in api),
      ('Camera module + persisted config','CameraModulePanel' in page and 'class CameraConfig' in models),
      ('Basler pypylon IP/serial capture','InstantCamera' in cam and 'IpAddress' in cam and 'SerialNumber' in cam and 'RetrieveResult' in cam),
      ('Generic URL capture + focus template','capture_url' in cam and 'focus_url_template' in cam),
      ('Trigger -> camera -> inspect -> OK/NG runner','camera.capture' in runner and 'runtime.run_test' in runner and 'pulse_result' in runner),
      ('Viewport zoom/pan','onWheel' in viewport and 'translate(' in viewport and 'scale(' in viewport),
      ('Collapsible control panels','leftOpen' in page and 'rightOpen' in page),
      ('Large OK/NG result box','INSPECTION RESULT' in page),
      ('Working Filter/Logic/Decision scopes','FILTER & PROCESSING' in (fe/'src/components/ComputerVision/ScopeEditorModal.tsx').read_text(encoding='utf-8') and 'DECISION IDE' in (fe/'src/components/ComputerVision/ScopeEditorModal.tsx').read_text(encoding='utf-8')),
      ('Global filtered image feeds ROI locator','filtered_test' in runtime and 'locate_all(program.master.rois, filtered_master, filtered_test' in runtime),
      ('Sequential/parallel station mode','station_execution' in models and 'ThreadPoolExecutor' in runtime),
      ('Real filter debug image store','VisionDebugStore' in (be/'app/services/vision_app/debug_store.py').read_text(encoding='utf-8') and 'scope-preview' in api),
      ('Program-wide Auto ROI family','AUTO ROI FAMILY · ALL STATIONS' in master and 'locator: RoiLocatorConfig' in models),
      ('Blur setting visualization','blur-preview' in api and 'Visualize blur on Master' in master),
      ('Benchmark view','BENCHMARK' in work and 'BenchmarkStep' in runtime),
      ('Restricted Decision DSL','ast.parse' in decision and "Only the 'result' variable" in decision),
      ('v0.8 handoff MD',(fe/'docs/llm_context/updates/v0800_computer_vision_production_pipeline.md').exists()),
      ('Context generator updated','Trigger runner' in (fe/'tools/generate_llm_context_map.py').read_text(encoding='utf-8') or 'Camera acquisition' in (fe/'tools/generate_llm_context_map.py').read_text(encoding='utf-8')),
    ]
    for label,ok in checks:print(f'[{"OK" if ok else "FAIL"}] {label}');fail += 0 if ok else 1
    n,errs=python_syntax(be)
    if errs:print('[FAIL] Python syntax');[print('  -',e) for e in errs];fail+=len(errs)
    else:print(f'[OK] Python syntax ({n} changed/new backend files)')
    tests=['tests/vision_app/test_vision_app_frame_v0100.py','tests/vision_app/test_vision_app_v0800.py']
    if importlib.util.find_spec('pytest') is None:print('[SKIP] pytest unavailable')
    else:
      p=subprocess.run([sys.executable,'-m','pytest','-q',*tests],cwd=str(be),text=True,capture_output=True)
      if p.returncode:print('[FAIL] Vision App regression tests');print((p.stdout+'\n'+p.stderr).strip());fail+=1
      else:print('[OK] Vision App regression tests');print(p.stdout.strip())
    t=ts_transpile(fe);tt=(t.stdout+'\n'+t.stderr).strip()
    if t.returncode==0:print('[OK] TypeScript syntax/transpile')
    elif 'Cannot find module' in tt or 'MODULE_NOT_FOUND' in tt:print('[SKIP] TypeScript module unavailable')
    else:print('[FAIL] TypeScript syntax/transpile');print(tt);fail+=1
    if not skip_build and (fe/'package.json').exists() and (fe/'node_modules').exists():
      p=subprocess.run(['npm','run','build'],cwd=str(fe));
      if p.returncode:print('[FAIL] Frontend npm build');fail+=1
      else:print('[OK] Frontend npm build')
    else:print('[SKIP] Frontend npm build')
    try:
      regenerate_context(fe,be);arch=fe/'docs/llm_context/SYSTEM_ARCHITECTURE.md';txt=arch.read_text(encoding='utf-8') if arch.exists() else ''
      ok='Computer Vision' in txt and ('Camera' in txt or 'Trigger' in txt);print(f'[{"OK" if ok else "FAIL"}] Regenerated Computer Vision architecture/context');fail += 0 if ok else 1
    except Exception as e:print('[FAIL] Context regeneration:',e);fail+=1
    if fail:print(f'[FAIL] v0.8.0 verification finished with {fail} issue(s).');return 1
    print('[OK] Computer Vision v0.8.0 Camera + Production Working Pipeline verified.');return 0

def main():
    ap=argparse.ArgumentParser();ap.add_argument('command',choices=['scan','apply','verify']);ap.add_argument('--frontend');ap.add_argument('--backend');ap.add_argument('--skip-build',action='store_true');a=ap.parse_args()
    try:
      fe,be=resolve_roots(a.frontend,a.backend)
      if a.command=='scan':return scan(fe,be)
      if a.command=='apply':return apply(fe,be)
      return verify(fe,be,a.skip_build)
    except Exception as e:print('[ERROR]',e);return 2
if __name__=='__main__':raise SystemExit(main())
